import { afterEach, beforeEach, describe, expect, test, vi } from 'vitest';
import { MemoryRouter } from 'react-router-dom';
import { cleanup, fireEvent, render, screen, waitFor } from '@testing-library/react';
import { consultasApi, especialidadesApi, medicosApi } from '../../src/api';
import { ToastProvider } from '../../src/contexts/ToastContext';
import { AgendarPage } from '../../src/pages/paciente/AgendarPage';

vi.mock('../../src/api', () => ({
  especialidadesApi: { listar: vi.fn(), criar: vi.fn() },
  medicosApi: { listar: vi.fn(), horarios: vi.fn(), criar: vi.fn() },
  consultasApi: { listar: vi.fn(), agendar: vi.fn() },
}));

const ESPECIALIDADES = [
  { id: 1, nome: 'Clínica Geral', precoCentavos: 15000 },
  { id: 2, nome: 'Cardiologia', precoCentavos: 30000 },
];

const MEDICOS = [
  { id: 1, nome: 'Dr. Carlos Almeida', especialidadeId: 1, duracaoConsultaMin: 30, ativo: true },
  { id: 9, nome: 'Dr. Inativo', especialidadeId: 1, duracaoConsultaMin: 30, ativo: false },
];

function montar() {
  return render(
    <MemoryRouter>
      <ToastProvider>
        <AgendarPage />
      </ToastProvider>
    </MemoryRouter>,
  );
}

function escolher(rotulo, valor) {
  fireEvent.change(screen.getByLabelText(rotulo), { target: { value: valor } });
}

async function montarComConsulta(data = '2026-10-26') {
  const utils = montar();
  await screen.findByRole('option', { name: /Clínica Geral/ });
  escolher('Especialidade', '1');
  await waitFor(() => expect(screen.getByRole('option', { name: /Dr\. Carlos Almeida/ })).toBeInTheDocument());
  escolher('Médico', '1');
  escolher('Data', data);
  await screen.findByRole('button', { name: '08:00' });
  return utils;
}

describe('pages/paciente/AgendarPage', () => {
  beforeEach(() => {
    localStorage.clear();
    vi.clearAllMocks();
    especialidadesApi.listar.mockResolvedValue(ESPECIALIDADES);
    medicosApi.listar.mockResolvedValue(MEDICOS);
    medicosApi.horarios.mockResolvedValue({ horarios: ['2026-10-26 08:00', '2026-10-26 08:30'] });
  });

  afterEach(() => {
    cleanup();
    localStorage.clear();
  });

  /**
   * @caso CT-INT-200
   * @nivel integracao
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RF03.2
   * @objetivo Oferecer as especialidades com o preço base formatado para escolha
   * @resultadoEsperado O select de especialidade lista as opções com nome e preço em reais
   */
  test.skip('AgendarPage lista as especialidades com o preço formatado', async () => {
    montar();

    const opcao = await screen.findByRole('option', { name: /Clínica Geral/ });
    expect(opcao.textContent).toContain('R$ 150,00');
    expect(screen.getByRole('option', { name: /Cardiologia/ }).textContent).toContain('R$ 300,00');
  });

  /**
   * @caso CT-INT-201
   * @nivel integracao
   * @atributo usabilidade
   * @subatributo protecao-contra-erro-do-usuario
   * @requisito RNF06
   * @objetivo Não deixar escolher médico antes da especialidade
   * @resultadoEsperado Select de médico fica desabilitado e sem consultar a API até a escolha
   */
  test('AgendarPage mantém o médico desabilitado até escolher a especialidade', async () => {
    montar();
    await screen.findByRole('option', { name: /Clínica Geral/ });

    expect(screen.getByLabelText('Médico')).toBeDisabled();
    expect(medicosApi.listar).not.toHaveBeenCalled();
    expect(screen.getByRole('option', { name: 'Escolha a especialidade' })).toBeInTheDocument();
  });

  /**
   * @caso CT-INT-202
   * @nivel integracao
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RF04.1
   * @objetivo Mostrar apenas os médicos ativos da especialidade escolhida
   * @resultadoEsperado Após escolher a especialidade, a lista tem o médico ativo e não o inativo
   */
  test('AgendarPage lista somente médicos ativos da especialidade escolhida', async () => {
    montar();
    await screen.findByRole('option', { name: /Clínica Geral/ });

    escolher('Especialidade', '1');

    await waitFor(() => expect(medicosApi.listar).toHaveBeenCalledWith('1'));
    await screen.findByRole('option', { name: /Dr\. Carlos Almeida/ });
    const textos = [...screen.getByLabelText('Médico').querySelectorAll('option')].map((opcao) => opcao.textContent);
    expect(textos.join(' ')).toContain('Dr. Carlos Almeida (30 min)');
    expect(textos.join(' ')).not.toContain('Dr. Inativo');
  });

  /**
   * @caso CT-INT-203
   * @nivel integracao
   * @atributo usabilidade
   * @subatributo protecao-contra-erro-do-usuario
   * @requisito RNF06
   * @objetivo Liberar a escolha de data somente depois que o médico está definido
   * @resultadoEsperado Campo de data fica desabilitado sem médico e habilitado após a escolha
   */
  test('AgendarPage habilita a data apenas após escolher o médico', async () => {
    montar();
    await screen.findByRole('option', { name: /Clínica Geral/ });
    escolher('Especialidade', '1');
    await screen.findByRole('option', { name: /Dr\. Carlos Almeida/ });

    expect(screen.getByLabelText('Data')).toBeDisabled();

    escolher('Médico', '1');

    expect(screen.getByLabelText('Data')).toBeEnabled();
  });

  /**
   * @caso CT-INT-204
   * @nivel integracao
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RF07.1, RN14
   * @objetivo Buscar os horários livres do médico na data escolhida
   * @resultadoEsperado A API de horários é chamada com médico e data e os botões aparecem
   */
  test('AgendarPage busca e exibe os horários do médico na data', async () => {
    montar();
    await screen.findByRole('option', { name: /Clínica Geral/ });
    escolher('Especialidade', '1');
    await waitFor(() => expect(medicosApi.listar).toHaveBeenCalledWith('1'));
    escolher('Médico', '1');
    escolher('Data', '2026-10-26');

    expect(await screen.findByRole('button', { name: '08:00' })).toBeInTheDocument();
    expect(medicosApi.horarios).toHaveBeenCalledWith('1', '2026-10-26');
  });

  /**
   * @caso CT-INT-205
   * @nivel integracao
   * @atributo usabilidade
   * @subatributo operabilidade
   * @requisito RNF06
   * @objetivo Mostrar o resumo do que será agendado antes da confirmação
   * @resultadoEsperado Ao escolher o horário, o resumo exibe médico, especialidade, data e duração
   */
  test('AgendarPage mostra o resumo do agendamento ao escolher o horário', async () => {
    await montarComConsulta();

    fireEvent.click(screen.getByRole('button', { name: '08:00' }));

    const resumo = document.getElementById('agendar-resumo');
    expect(resumo).toHaveTextContent('Dr. Carlos Almeida');
    expect(resumo).toHaveTextContent('Clínica Geral');
    expect(resumo).toHaveTextContent('26/10/2026 08:00');
    expect(resumo).toHaveTextContent('30 minutos');
  });

  /**
   * @caso CT-INT-206
   * @nivel integracao
   * @atributo usabilidade
   * @subatributo protecao-contra-erro-do-usuario
   * @requisito RNF06
   * @objetivo Bloquear a confirmação enquanto não há horário escolhido
   * @resultadoEsperado Botão de confirmar fica desabilitado sem horário e habilitado depois da escolha
   */
  test('AgendarPage desabilita a confirmação sem horário escolhido', async () => {
    await montarComConsulta();

    expect(document.getElementById('agendar-confirmar')).toBeDisabled();

    fireEvent.click(screen.getByRole('button', { name: '08:00' }));

    expect(document.getElementById('agendar-confirmar')).toBeEnabled();
  });

  /**
   * @caso CT-INT-207
   * @nivel integracao
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RF08.1, RF08.2
   * @objetivo Enviar o agendamento com o horário escolhido e confirmar o valor calculado
   * @resultadoEsperado O POST recebe médico e início, o toast confirma e o resumo é limpo
   */
  test('AgendarPage envia a solicitação e confirma o valor da consulta', async () => {
    consultasApi.agendar.mockResolvedValue({
      id: 5,
      medicoNome: 'Dr. Carlos Almeida',
      inicio: '2026-10-26 08:00',
      valorCentavos: 15000,
    });
    await montarComConsulta();

    fireEvent.click(screen.getByRole('button', { name: '08:00' }));
    fireEvent.click(document.getElementById('agendar-confirmar'));

    await waitFor(() => expect(consultasApi.agendar).toHaveBeenCalledWith({ medicoId: 1, inicio: '2026-10-26 08:00' }));
    expect(await screen.findByText('Consulta agendada')).toBeInTheDocument();
    expect(await screen.findByText(/Dr\. Carlos Almeida em 26\/10\/2026 08:00 \(R\$\s150,00\)\./)).toBeInTheDocument();
    await waitFor(() => expect(document.getElementById('agendar-resumo')).toBeNull());
  });

  /**
   * @caso CT-INT-208
   * @nivel integracao
   * @atributo confiabilidade
   * @subatributo tolerancia-a-falhas
   * @requisito RNF04
   * @objetivo Mostrar a regra de negócio violada sem perder o horário escolhido
   * @resultadoEsperado Erro do servidor vira alerta no formulário e o resumo permanece na tela
   */
  test('AgendarPage exibe o erro do servidor mantendo o horário escolhido', async () => {
    consultasApi.agendar.mockRejectedValue(
      new Error('O paciente já possui uma consulta agendada nesta especialidade.'),
    );
    await montarComConsulta();

    fireEvent.click(screen.getByRole('button', { name: '08:00' }));
    fireEvent.click(document.getElementById('agendar-confirmar'));

    const aviso = await screen.findByRole('alert');
    expect(aviso).toHaveAttribute('id', 'agendar-mensagem');
    expect(aviso).toHaveTextContent('O paciente já possui uma consulta agendada nesta especialidade.');
    expect(document.getElementById('agendar-resumo')).not.toBeNull();
    expect(consultasApi.agendar).toHaveBeenCalledTimes(1);
  });

  /**
   * @caso CT-INT-209
   * @nivel integracao
   * @atributo usabilidade
   * @subatributo protecao-contra-erro-do-usuario
   * @requisito RNF06
   * @objetivo Evitar agendar com médico de outra especialidade após trocar a escolha
   * @resultadoEsperado Trocar a especialidade zera o médico, o horário e o resumo
   */
  test('AgendarPage limpa médico e horário ao trocar a especialidade', async () => {
    await montarComConsulta();
    fireEvent.click(screen.getByRole('button', { name: '08:00' }));
    expect(document.getElementById('agendar-resumo')).not.toBeNull();

    escolher('Especialidade', '2');

    expect(screen.getByLabelText('Médico')).toHaveValue('');
    expect(document.getElementById('agendar-resumo')).toBeNull();
    await waitFor(() => expect(medicosApi.listar).toHaveBeenCalledWith('2'));
  });
});

frontend/__testes__/unitario/client-http.source:
import { afterEach, beforeEach, describe, expect, test, vi } from 'vitest';
import { ApiError, registrarExpiracaoSessao, request, tokenStorage } from '../../src/api/client';

function respostaHttp({ status = 200, dados = undefined, jsonInvalido = false } = {}) {
  return {
    status,
    ok: status >= 200 && status < 300,
    json: vi.fn(() => (jsonInvalido ? Promise.reject(new Error('JSON inválido')) : Promise.resolve(dados))),
  };
}

describe('api/client', () => {
  let aoExpirar;

  beforeEach(() => {
    localStorage.clear();
    vi.stubGlobal('fetch', vi.fn());
    aoExpirar = vi.fn();
    registrarExpiracaoSessao(aoExpirar);
  });

  afterEach(() => {
    vi.unstubAllGlobals();
    localStorage.clear();
  });

  /**
   * @caso CT-UNI-141
   * @nivel unitario
   * @atributo seguranca
   * @subatributo confidencialidade
   * @requisito RNF02
   * @objetivo Guardar a sessão do usuário na chave oficial do armazenamento local
   * @resultadoEsperado tokenStorage salva, lê e remove o token na chave "clinica.token"
   */
  test('tokenStorage usa a chave clinica.token do navegador', () => {
    tokenStorage.salvar('abc123');
    expect(localStorage.getItem('clinica.token')).toBe('abc123');
    expect(tokenStorage.obter()).toBe('abc123');
    tokenStorage.remover();
    expect(tokenStorage.obter()).toBeNull();
    expect(localStorage.getItem('clinica.token')).toBeNull();
  });

  /**
   * @caso CT-UNI-142
   * @nivel unitario
   * @atributo seguranca
   * @subatributo autenticidade
   * @requisito RF01.2, RNF02
   * @objetivo Enviar o token da sessão no cabeçalho Authorization das requisições
   * @resultadoEsperado Com token salvo, o fetch recebe Authorization: Bearer <token>
   */
  test('request envia Authorization Bearer quando há token salvo', async () => {
    tokenStorage.salvar('tok-1');
    vi.mocked(fetch).mockResolvedValue(respostaHttp({ dados: [] }));

    await request('/consultas');

    const [, opcoes] = fetch.mock.calls[0];
    expect(opcoes.method).toBe('GET');
    expect(opcoes.headers.Authorization).toBe('Bearer tok-1');
  });

  /**
   * @caso CT-UNI-143
   * @nivel unitario
   * @atributo seguranca
   * @subatributo confidencialidade
   * @requisito RF01.2
   * @objetivo Não enviar credencial alguma quando o usuário não tem sessão
   * @resultadoEsperado Sem token, o cabeçalho da requisição não tem Authorization
   */
  test('request não envia Authorization sem token salvo', async () => {
    vi.mocked(fetch).mockResolvedValue(respostaHttp({ dados: [] }));

    await request('/consultas');

    const [, opcoes] = fetch.mock.calls[0];
    expect(opcoes.headers).not.toHaveProperty('Authorization');
  });

  /**
   * @caso CT-UNI-144
   * @nivel unitario
   * @atributo compatibilidade
   * @subatributo interoperabilidade
   * @requisito RF08.1
   * @objetivo Enviar o corpo do agendamento serializado em JSON com o cabeçalho adequado
   * @resultadoEsperado POST envia Content-Type application/json e o corpo serializado
   */
  test('request serializa o corpo em JSON nos métodos que recebem dados', async () => {
    vi.mocked(fetch).mockResolvedValue(respostaHttp({ status: 201, dados: { id: 9 } }));

    const dados = await request('/consultas', { metodo: 'POST', corpo: { medicoId: 1, inicio: '2026-10-26 08:00' } });

    const [, opcoes] = fetch.mock.calls[0];
    expect(opcoes.headers['Content-Type']).toBe('application/json');
    expect(opcoes.body).toBe('{"medicoId":1,"inicio":"2026-10-26 08:00"}');
    expect(dados).toEqual({ id: 9 });
  });

  /**
   * @caso CT-UNI-145
   * @nivel unitario
   * @atributo compatibilidade
   * @subatributo interoperabilidade
   * @requisito RF10.3
   * @objetivo Montar a query string da listagem ignorando filtros vazios
   * @resultadoEsperado Parâmetros "", null e undefined não aparecem na URL e os preenchidos aparecem
   */
  test('request ignora parâmetros vazios na query string', async () => {
    vi.mocked(fetch).mockResolvedValue(respostaHttp({ dados: [] }));

    await request('/consultas', { params: { dataInicio: '', status: null, medicoId: undefined, pacienteId: 2 } });

    expect(fetch.mock.calls[0][0].toString()).toBe('http://localhost:3000/api/consultas?pacienteId=2');
  });

  /**
   * @caso CT-UNI-146
   * @nivel unitario
   * @atributo compatibilidade
   * @subatributo interoperabilidade
   * @requisito RF10.3
   * @objetivo Enviar todos os filtros preenchidos da listagem da recepção
   * @resultadoEsperado A URL inclui dataInicio, dataFim e status na ordem dos parâmetros
   */
  test('request envia os filtros preenchidos como query string', async () => {
    vi.mocked(fetch).mockResolvedValue(respostaHttp({ dados: [] }));

    await request('/consultas', { params: { dataInicio: '2026-10-19', dataFim: '2026-10-31', status: 'AGENDADA' } });

    expect(fetch.mock.calls[0][0].toString()).toBe(
      'http://localhost:3000/api/consultas?dataInicio=2026-10-19&dataFim=2026-10-31&status=AGENDADA',
    );
  });

  /**
   * @caso CT-UNI-147
   * @nivel unitario
   * @atributo confiabilidade
   * @subatributo tolerancia-a-falhas
   * @requisito RNF04
   * @objetivo Tratar resposta 204 sem corpo sem lançar exceção
   * @resultadoEsperado DELETE com 204 devolve null
   */
  test('request devolve null para resposta 204 sem corpo', async () => {
    vi.mocked(fetch).mockResolvedValue({ status: 204, ok: true, json: vi.fn() });

    const resultado = await request('/medicos/1/bloqueios/2', { metodo: 'DELETE' });

    expect(resultado).toBeNull();
  });

  /**
   * @caso CT-UNI-148
   * @nivel unitario
   * @atributo confiabilidade
   * @subatributo tolerancia-a-falhas
   * @requisito RNF04
   * @objetivo Converter o erro da API em exceção com status, código e mensagem
   * @resultadoEsperado Erro 422 REGRA_NEGOCIO vira ApiError com os três campos preenchidos
   */
  test('request transforma o contrato de erro da API em ApiError', async () => {
    vi.mocked(fetch).mockResolvedValue(
      respostaHttp({
        status: 422,
        dados: { erro: { codigo: 'REGRA_NEGOCIO', mensagem: 'A consulta já começou.' } },
      }),
    );

    const erro = await request('/consultas/1/cancelar', { metodo: 'POST' }).catch((e) => e);

    expect(erro).toBeInstanceOf(ApiError);
    expect(erro.status).toBe(422);
    expect(erro.codigo).toBe('REGRA_NEGOCIO');
    expect(erro.message).toBe('A consulta já começou.');
  });

  /**
   * @caso CT-UNI-149
   * @nivel unitario
   * @atributo compatibilidade
   * @subatributo interoperabilidade
   * @requisito RF01.3
   * @objetivo Devolver o corpo JSON das respostas de sucesso sem alteração
   * @resultadoEsperado O login devolve token e usuário exatamente como a API enviou
   */
  test('request devolve o JSON das respostas de sucesso', async () => {
    vi.mocked(fetch).mockResolvedValue(
      respostaHttp({ dados: { token: 'jwt', usuario: { id: 1, nome: 'Ana Pereira', perfil: 'PACIENTE' } } }),
    );

    const dados = await request('/auth/login', { metodo: 'POST', corpo: { email: 'ana@email.com', senha: 'Senha123' } });

    expect(dados.token).toBe('jwt');
    expect(dados.usuario.perfil).toBe('PACIENTE');
  });

  /**
   * @caso CT-UNI-150
   * @nivel unitario
   * @atributo confiabilidade
   * @subatributo tolerancia-a-falhas
   * @requisito RNF04
   * @objetivo Enviar mensagem genérica em português quando a API não devolve o contrato de erro
   * @resultadoEsperado Erro sem campo "erro" vira ApiError com código DESCONHECIDO e mensagem padrão
   */
  test('request usa código e mensagem padrão quando a resposta não tem contrato de erro', async () => {
    vi.mocked(fetch).mockResolvedValue(respostaHttp({ status: 500, dados: { qualquer: 1 } }));

    const erro = await request('/relatorios').catch((e) => e);

    expect(erro.codigo).toBe('DESCONHECIDO');
    expect(erro.message).toBe('Erro inesperado.');
  });

  /**
   * @caso CT-UNI-151
   * @nivel unitario
   * @atributo confiabilidade
   * @subatributo tolerancia-a-falhas
   * @requisito RNF04
   * @objetivo Converter falha de rede em mensagem legível em português
   * @resultadoEsperado Fetch rejeitado vira ApiError com status 0, código REDE e a mensagem de conexão
   */
  test('request vira erro REDE quando o servidor não responde', async () => {
    vi.mocked(fetch).mockRejectedValue(new Error('offline'));

    const erro = await request('/consultas').catch((e) => e);

    expect(erro.status).toBe(0);
    expect(erro.codigo).toBe('REDE');
    expect(erro.message).toBe('Não foi possível conectar ao servidor.');
  });

  /**
   * @caso CT-UNI-152
   * @nivel unitario
   * @atributo seguranca
   * @subatributo autenticidade
   * @requisito RNF02
   * @objetivo Encerrar a sessão quando a API responde 401 com token enviado
   * @resultadoEsperado Com token salvo, o 401 dispara o callback de expiração de sessão registrado
   */
  test('request avisa a expiração da sessão em 401 com token', async () => {
    tokenStorage.salvar('expirado');
    vi.mocked(fetch).mockResolvedValue(
      respostaHttp({ status: 401, dados: { erro: { codigo: 'NAO_AUTENTICADO', mensagem: 'Token inválido ou expirado.' } } }),
    );

    await request('/auth/me').catch(() => {});

    expect(aoExpirar).toHaveBeenCalledTimes(1);
  });

  /**
   * @caso CT-UNI-153
   * @nivel unitario
   * @atributo seguranca
   * @subatributo confidencialidade
   * @requisito RNF02
   * @objetivo Não tentar encerrar uma sessão inexistente em 401 sem token
   * @resultadoEsperado Sem token salvo, o 401 não dispara o callback de expiração
   */
  test('request não dispara expiração de sessão em 401 sem token', async () => {
    vi.mocked(fetch).mockResolvedValue(
      respostaHttp({ status: 401, dados: { erro: { codigo: 'NAO_AUTENTICADO', mensagem: 'Credenciais erradas.' } } }),
    );

    await request('/auth/me').catch(() => {});

    expect(aoExpirar).not.toHaveBeenCalled();
  });

  /**
   * @caso CT-UNI-154
   * @nivel unitario
   * @atributo confiabilidade
   * @subatributo recuperabilidade
   * @requisito RNF04
   * @objetivo Não quebrar quando uma resposta de sucesso vem sem JSON válido
   * @resultadoEsperado Corpo não JSON em sucesso devolve null em vez de lançar exceção
   */
  test('request devolve null quando o JSON da resposta de sucesso é inválido', async () => {
    vi.mocked(fetch).mockResolvedValue(respostaHttp({ jsonInvalido: true }));

    const resultado = await request('/relatorios/resumo');

    expect(resultado).toBeNull();
  });
});

