import { afterEach, beforeEach, describe, expect, test, vi } from 'vitest';
import { cleanup, fireEvent, render, screen, waitFor } from '@testing-library/react';
import { medicosApi } from '../../src/api';
import { SeletorHorarios } from '../../src/components/SeletorHorarios';

vi.mock('../../src/api', () => ({
  medicosApi: { horarios: vi.fn() },
}));

function montar(props = {}) {
  return render(
    <SeletorHorarios
      id="agendar-horarios"
      medicoId="1"
      data="2026-10-26"
      selecionado={null}
      onEscolher={vi.fn()}
      recarregarChave={0}
      {...props}
    />,
  );
}

describe('components/SeletorHorarios', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  afterEach(cleanup);

  /**
   * @caso CT-INT-180
   * @nivel integracao
   * @atributo adequacao-funcional
   * @subatributo pertinencia
   * @requisito RF07.1
   * @objetivo Não consultar a API quando o usuário ainda não escolheu médico e data
   * @resultadoEsperado Sem médico ou data, nenhuma chamada é feita e o grupo fica vazio
   */
  test('SeletorHorarios não busca horários sem médico ou sem data', () => {
    montar({ medicoId: '', data: '' });

    expect(medicosApi.horarios).not.toHaveBeenCalled();
    const grupo = document.getElementById('agendar-horarios');
    expect(grupo).toHaveAttribute('aria-busy', 'false');
    expect(grupo.querySelectorAll('button')).toHaveLength(0);
  });

  /**
   * @caso CT-INT-181
   * @nivel integracao
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RF07.1, RN14
   * @objetivo Listar os horários livres devolvidos pela API como botões escolhíveis
   * @resultadoEsperado Os horários viram botões com data-inicio e a hora visível no rótulo
   */
  test('SeletorHorarios lista os horários devolvidos pela API', async () => {
    medicosApi.horarios.mockResolvedValue({ horarios: ['2026-10-26 08:00', '2026-10-26 08:30'] });

    montar();

    expect(medicosApi.horarios).toHaveBeenCalledWith('1', '2026-10-26');
    expect(await screen.findByRole('button', { name: '08:00' })).toHaveAttribute('data-inicio', '2026-10-26 08:00');
    expect(screen.getByRole('button', { name: '08:30' })).toHaveAttribute('data-inicio', '2026-10-26 08:30');
  });

  /**
   * @caso CT-INT-182
   * @nivel integracao
   * @atributo usabilidade
   * @subatributo operabilidade
   * @requisito RNF06
   * @objetivo Avisar em português quando não há nenhum horário livre na data
   * @resultadoEsperado Lista vazia mostra o aviso "Nenhum horário livre nesta data. Tente outro dia."
   */
  test('SeletorHorarios avisa quando a data não tem horários livres', async () => {
    medicosApi.horarios.mockResolvedValue({ horarios: [] });

    montar({ data: '2026-10-27' });

    expect(await screen.findByText('Nenhum horário livre nesta data. Tente outro dia.')).toBeInTheDocument();
  });

  /**
   * @caso CT-INT-183
   * @nivel integracao
   * @atributo confiabilidade
   * @subatributo tolerancia-a-falhas
   * @requisito RNF04
   * @objetivo Exibir a mensagem de erro da API sem quebrar o formulário de agendamento
   * @resultadoEsperado Falha na busca aparece como aviso com o texto do erro
   */
  test('SeletorHorarios exibe o erro da API como aviso', async () => {
    medicosApi.horarios.mockRejectedValue(new Error('Data inválida. Use o formato AAAA-MM-DD.'));

    montar({ data: '2026-13-40' });

    expect(await screen.findByText('Data inválida. Use o formato AAAA-MM-DD.')).toBeInTheDocument();
  });

  /**
   * @caso CT-INT-184
   * @nivel integracao
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN17
   * @objetivo Entregar o horário escolhido integralmente ao formulário de agendamento
   * @resultadoEsperado Clicar no botão chama onEscolher com "AAAA-MM-DD HH:mm" completo
   */
  test('SeletorHorarios entrega o horário completo ao clicar', async () => {
    medicosApi.horarios.mockResolvedValue({ horarios: ['2026-10-26 08:00', '2026-10-26 08:30'] });
    const aoEscolher = vi.fn();

    montar({ onEscolher: aoEscolher });

    fireEvent.click(await screen.findByRole('button', { name: '08:30' }));

    expect(aoEscolher).toHaveBeenCalledWith('2026-10-26 08:30');
  });

  /**
   * @caso CT-INT-185
   * @nivel integracao
   * @atributo usabilidade
   * @subatributo reconhecibilidade
   * @requisito RNF06
   * @objetivo Destacar o horário já escolhido pelo usuário
   * @resultadoEsperado O horário selecionado tem aria-pressed true e a classe selecionado
   */
  test('SeletorHorarios marca com aria-pressed o horário selecionado', async () => {
    medicosApi.horarios.mockResolvedValue({ horarios: ['2026-10-26 08:00', '2026-10-26 08:30'] });

    montar({ selecionado: '2026-10-26 08:00' });

    const escolhido = await screen.findByRole('button', { name: '08:00' });
    expect(escolhido).toHaveAttribute('aria-pressed', 'true');
    expect(escolhido).toHaveClass('selecionado');
    expect(screen.getByRole('button', { name: '08:30' })).toHaveAttribute('aria-pressed', 'false');
  });

  /**
   * @caso CT-INT-186
   * @nivel integracao
   * @atributo manutenibilidade
   * @subatributo testabilidade
   * @requisito RNF07
   * @objetivo Recarregar os horários quando a página pede (após um novo agendamento)
   * @resultadoEsperado Mudar recarregarChave dispara uma nova chamada à API de horários
   */
  test('SeletorHorarios busca de novo ao mudar recarregarChave', async () => {
    medicosApi.horarios.mockResolvedValue({ horarios: ['2026-10-26 08:00'] });

    const { rerender } = render(
      <SeletorHorarios id="agendar-horarios" medicoId="1" data="2026-10-26" selecionado={null} onEscolher={vi.fn()} recarregarChave={0} />,
    );
    await screen.findByRole('button', { name: '08:00' });

    rerender(
      <SeletorHorarios id="agendar-horarios" medicoId="1" data="2026-10-26" selecionado={null} onEscolher={vi.fn()} recarregarChave={1} />,
    );

    await waitFor(() => expect(medicosApi.horarios).toHaveBeenCalledTimes(2));
  });

  /**
   * @caso CT-INT-187
   * @nivel integracao
   * @atributo usabilidade
   * @subatributo acessibilidade
   * @requisito RNF06
   * @objetivo Anunciar o grupo como ocupado enquanto os horários carregam
   * @resultadoEsperado aria-busy fica true durante a busca e volta a false ao concluir
   */
  test('SeletorHorarios mantém aria-busy true enquanto carrega', async () => {
    let resolver;
    medicosApi.horarios.mockReturnValue(new Promise((resolverExterno) => { resolver = resolverExterno; }));

    montar();

    expect(document.getElementById('agendar-horarios')).toHaveAttribute('aria-busy', 'true');
    resolver({ horarios: [] });
    await waitFor(() => expect(document.getElementById('agendar-horarios')).toHaveAttribute('aria-busy', 'false'));
  });
});

frontend/__testes__/integracao/login-pag.source:
import { afterEach, beforeEach, describe, expect, test, vi } from 'vitest';
import { MemoryRouter, Route, Routes } from 'react-router-dom';
import { cleanup, fireEvent, render, screen, waitFor } from '@testing-library/react';
import { authApi } from '../../src/api';
import { AuthProvider } from '../../src/contexts/AuthContext';
import { ToastProvider } from '../../src/contexts/ToastContext';
import { LoginPage } from '../../src/pages/LoginPage';

vi.mock('../../src/api', () => ({
  authApi: { login: vi.fn(), me: vi.fn(), registrar: vi.fn() },
  especialidadesApi: { listar: vi.fn(), criar: vi.fn() },
  medicosApi: { listar: vi.fn(), horarios: vi.fn(), criar: vi.fn() },
  pacientesApi: { listar: vi.fn(), criar: vi.fn() },
  consultasApi: { listar: vi.fn(), agendar: vi.fn() },
  adminApi: { definirAtivo: vi.fn(), resumo: vi.fn() },
}));

function montar() {
  return render(
    <MemoryRouter initialEntries={['/login']}>
      <ToastProvider>
        <AuthProvider>
          <Routes>
            <Route path="/login" element={<LoginPage />} />
            <Route path="/cadastro" element={<div>tela de cadastro</div>} />
            <Route path="/paciente" element={<div>area do paciente</div>} />
          </Routes>
        </AuthProvider>
      </ToastProvider>
    </MemoryRouter>,
  );
}

function preencher(email, senha) {
  fireEvent.change(screen.getByLabelText('E-mail'), { target: { value: email } });
  fireEvent.change(screen.getByLabelText('Senha'), { target: { value: senha } });
}

describe('pages/LoginPage', () => {
  beforeEach(() => {
    localStorage.clear();
    vi.clearAllMocks();
  });

  afterEach(() => {
    cleanup();
    localStorage.clear();
  });

  /**
   * @caso CT-INT-194
   * @nivel integracao
   * @atributo usabilidade
   * @subatributo acessibilidade
   * @requisito RNF06
   * @objetivo Apresentar o formulário com rótulos associados e botão de envio identificável
   * @resultadoEsperado Os campos de e-mail e senha são encontrados por rótulo e o botão Entrar está presente
   */
  test('LoginPage exibe os campos de e-mail e senha com rótulos associados', () => {
    montar();

    expect(screen.getByLabelText('E-mail')).toHaveAttribute('id', 'login-email');
    expect(screen.getByLabelText('Senha')).toHaveAttribute('id', 'login-senha');
    expect(screen.getByRole('button', { name: 'Entrar' })).toHaveAttribute('id', 'login-entrar');
    expect(document.getElementById('form-login')).not.toBeNull();
  });

  /**
   * @caso CT-INT-195
   * @nivel integracao
   * @atributo usabilidade
   * @subatributo operabilidade
   * @requisito RF02.1
   * @objetivo Oferecer o caminho de auto-cadastro para quem ainda não tem conta
   * @resultadoEsperado O link "Cadastre-se como paciente" leva para a tela de cadastro
   */
  test('LoginPage navega para a tela de cadastro pelo link indicado', () => {
    montar();

    fireEvent.click(screen.getByText('Cadastre-se como paciente'));

    expect(screen.getByText('tela de cadastro')).toBeInTheDocument();
  });

  /**
   * @caso CT-INT-196
   * @nivel integracao
   * @atributo usabilidade
   * @subatributo operabilidade
   * @requisito RNF06
   * @objetivo Mostrar a recusa de credenciais em português sem sair da tela de login
   * @resultadoEsperado Senha errada exibe alerta com a mensagem da API e mantém /login
   */
  test('LoginPage exibe erro em português para senha incorreta', async () => {
    authApi.login.mockRejectedValue(new Error('E-mail ou senha inválidos.'));
    montar();

    preencher('recepcao@clinica.com', 'senha-errada');
    fireEvent.click(screen.getByRole('button', { name: 'Entrar' }));

    const aviso = await screen.findByRole('alert');
    expect(aviso).toHaveAttribute('id', 'login-mensagem');
    expect(aviso).toHaveTextContent('E-mail ou senha inválidos.');
    expect(authApi.login).toHaveBeenCalledWith('recepcao@clinica.com', 'senha-errada');
    expect(screen.queryByText('area do paciente')).not.toBeInTheDocument();
  });

  /**
   * @caso CT-INT-197
   * @nivel integracao
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RF01.1, RF01.3
   * @objetivo Entrar com credenciais válidas e seguir para a área do perfil
   * @resultadoEsperado Login PACIENTE salva o token, mostra o toast de boas-vindas e vai para /paciente
   */
  test('LoginPage autentica e leva o paciente para a área dele', async () => {
    authApi.login.mockResolvedValue({
      token: 'tok-1',
      usuario: { id: 1, nome: 'Ana Pereira', perfil: 'PACIENTE' },
    });
    montar();

    preencher('ana@email.com', 'Senha123');
    fireEvent.click(screen.getByRole('button', { name: 'Entrar' }));

    await waitFor(() => expect(screen.getByText('area do paciente')).toBeInTheDocument());
    expect(localStorage.getItem('clinica.token')).toBe('tok-1');
    expect(await screen.findByText('Que bom ter você de volta, Ana.')).toBeInTheDocument();
  });

  /**
   * @caso CT-INT-198
   * @nivel integracao
   * @atributo usabilidade
   * @subatributo protecao-contra-erro-do-usuario
   * @requisito RNF06
   * @objetivo Impedir envio repetido enquanto o login está em andamento
   * @resultadoEsperado Durante a requisição o botão fica desabilitado e mostra "Entrando..."
   */
  test('LoginPage desabilita o botão enquanto o login está em andamento', async () => {
    let resolver;
    authApi.login.mockReturnValue(new Promise((resolverExterno) => { resolver = resolverExterno; }));
    montar();

    preencher('ana@email.com', 'Senha123');
    fireEvent.click(screen.getByRole('button', { name: 'Entrar' }));

    expect(screen.getByRole('button', { name: 'Entrando...' })).toBeDisabled();

    resolver({ token: 'tok-2', usuario: { id: 1, nome: 'Ana Pereira', perfil: 'PACIENTE' } });
    await waitFor(() => expect(screen.getByText('area do paciente')).toBeInTheDocument());
  });

  /**
   * @caso CT-INT-199
   * @nivel integracao
   * @atributo seguranca
   * @subatributo confidencialidade
   * @requisito RF01.2
   * @objetivo Não exibir o formulário de login para quem já tem sessão válida
   * @resultadoEsperado Com sessão restaurada, a página redireciona sem mostrar os campos
   */
  test('LoginPage redireciona o usuário já autenticado sem exibir o formulário', async () => {
    localStorage.setItem('clinica.token', 'tok-1');
    authApi.me.mockResolvedValue({ id: 1, nome: 'Ana Pereira', perfil: 'PACIENTE' });

    montar();

    await waitFor(() => expect(screen.getByText('area do paciente')).toBeInTheDocument());
    expect(screen.queryByLabelText('E-mail')).not.toBeInTheDocument();
  });
});

frontend/__testes__/unitario/formatadore.source:
import { afterEach, describe, expect, test, vi } from 'vitest';
import {
  NOMES_DIAS,
  STATUS_CONSULTA,
  estaAtiva,
  formatarDataHora,
  formatarMoeda,
  hojeISO,
} from '../../src/utils/formatadores';

// O toLocaleString('pt-BR') usa um espaço não separável entre "R$" e o valor.
const moeda = (centavos) => formatarMoeda(centavos).replace(/\u00a0/g, ' ');

describe('utils/formatadores', () => {
  afterEach(() => {
    vi.useRealTimers();
  });

  /**
   * @caso CT-UNI-128
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN22, RF08.2
   * @objetivo Exibir o preço base da especialidade em reais no formato brasileiro
   * @resultadoEsperado formatarMoeda(15000) devolve "R$ 150,00"
   */
  test('formatarMoeda converte centavos em reais no formato pt-BR', () => {
    expect(moeda(15000)).toBe('R$ 150,00');
  });

  /**
   * @caso CT-UNI-129
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN24
   * @objetivo Exibir valor zero de retorno gratuito sem casas decimais estranhas
   * @resultadoEsperado formatarMoeda(0) devolve "R$ 0,00"
   */
  test('formatarMoeda mostra zero para o retorno gratuito', () => {
    expect(moeda(0)).toBe('R$ 0,00');
  });

  /**
   * @caso CT-UNI-130
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN23
   * @objetivo Exibir o valor com desconto de 10% do paciente idoso já arredondado
   * @resultadoEsperado formatarMoeda(27000) devolve "R$ 270,00"
   */
  test('formatarMoeda exibe o valor do desconto do paciente idoso', () => {
    expect(moeda(27000)).toBe('R$ 270,00');
  });

  /**
   * @caso CT-UNI-131
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RNF06
   * @objetivo Converter data e hora do padrão do sistema para o formato brasileiro com hora
   * @resultadoEsperado formatarDataHora("2026-10-19 08:30") devolve "19/10/2026 08:30"
   */
  test('formatarDataHora converte data e hora para DD/MM/AAAA HH:mm', () => {
    expect(formatarDataHora('2026-10-19 08:30')).toBe('19/10/2026 08:30');
  });

  /**
   * @caso CT-UNI-132
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RNF06
   * @objetivo Converter apenas a data sem inventar uma hora
   * @resultadoEsperado formatarDataHora("2026-10-19") devolve "19/10/2026"
   */
  test('formatarDataHora converte data sem hora para DD/MM/AAAA', () => {
    expect(formatarDataHora('2026-10-19')).toBe('19/10/2026');
  });

  /**
   * @caso CT-UNI-133
   * @nivel unitario
   * @atributo confiabilidade
   * @subatributo maturidade
   * @requisito RNF06
   * @objetivo Tratar entrada vazia de data sem lançar exceção
   * @resultadoEsperado formatarDataHora("") devolve string vazia
   */
  test('formatarDataHora devolve string vazia para entrada vazia', () => {
    expect(formatarDataHora('')).toBe('');
  });

  /**
   * @caso CT-UNI-134
   * @nivel unitario
   * @atributo confiabilidade
   * @subatributo maturidade
   * @requisito RNF06
